not_cmp() { ! cmp -s "$@"; }
not_grep() { ! grep "$@"; }
not_out_has() { ! printf '%s' "$OUT" | grep -q -- "$1"; }
reason_grep() { printf '%s' "$OUT" | jq -r .reason | grep "$@"; }
